"""Cyclic / cactus structured core validation."""
import json, random, sys, time
sys.path.insert(0, '/workspace/tmp')
sys.path.insert(0, '/workspace/submission')
import ref, main as M
from bigtest import forward_Z, Z_evidence


def randasn(rnd, lo=1, hi=4000000):
    return rnd.randint(lo, hi)


def gen_cyclic(seed):
    rnd = random.Random(seed)
    style = rnd.randint(0, 4)
    rib = []
    if style <= 1:
        # single cycle, paths wrapping around
        N = rnd.randint(4, 24)
        cyc = []
        used = set()
        while len(cyc) < N:
            a = randasn(rnd)
            if a not in used:
                used.add(a)
                cyc.append(a)
        for i in range(N):
            L = rnd.randint(2, min(6, N - 2))
            p = [cyc[(i + j) % N] for j in range(L + 1)]
            if rnd.random() < 0.5:
                p = p[::-1]
            rib.append({'path': p, 'count': rnd.randint(1, 5)})
            if rnd.random() < 0.4:
                rib.append({'path': p[::-1], 'count': rnd.randint(1, 5)})
    elif style == 2:
        # cactus: several cycles sharing one articulation node
        ncyc = rnd.randint(2, 4)
        shared = randasn(rnd)
        allnodes = []
        for c in range(ncyc):
            N = rnd.randint(3, 8)
            nodes = [shared] + [randasn(rnd) for _ in range(N - 1)]
            for i in range(N):
                L = rnd.randint(2, min(4, N - 1))
                p = [nodes[(i + j) % N] for j in range(L + 1)]
                if rnd.random() < 0.5:
                    p = p[::-1]
                rib.append({'path': p, 'count': rnd.randint(1, 4)})
    elif style == 3:
        # cycles connected in a chain by shared nodes
        ncyc = rnd.randint(2, 5)
        prev_shared = None
        for c in range(ncyc):
            N = rnd.randint(4, 9)
            nodes = [randasn(rnd) for _ in range(N)]
            if prev_shared is not None:
                nodes[0] = prev_shared
            prev_shared = nodes[N // 2]
            for i in range(N):
                L = rnd.randint(2, min(5, N - 2))
                p = [nodes[(i + j) % N] for j in range(L + 1)]
                if rnd.random() < 0.5:
                    p = p[::-1]
                rib.append({'path': p, 'count': rnd.randint(1, 4)})
    else:
        # complete-ish small graph: all 3-subsets of a small node set
        nn = rnd.randint(4, 7)
        nodes = rnd.sample(range(1, 4000), nn)
        for _ in range(rnd.randint(4, 25)):
            p = rnd.sample(nodes, rnd.randint(2, nn))
            rib.append({'path': p, 'count': rnd.randint(1, 4)})
    agg = {}
    for rec in rib:
        p = ref.normalize(rec['path'], set())
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        agg[tuple(p)] = agg.get(tuple(p), 0) + rec['count']
    if not agg:
        return None
    f_mine, r_mine = M.peel(list(agg.items()))
    final, rounds = ref.ref_peel(agg)
    if f_mine != final or r_mine != rounds:
        return ('PEEL', agg, (f_mine, r_mine), (final, rounds))
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(ref.canon(p[i], p[i + 1]))
    if not core or len(core) > 64:
        return None
    occs = ref.ref_occurrences(final)
    adj = ref.scope_graph(occs, core)
    order = ref.find_order(adj)
    if order is None:
        return None
    vi = {l: i for i, l in enumerate(order)}
    occs_m = M.collect_occurrences(final)
    factors = [M.build_factor(l, occs_m.get(l, []), vi) for l in order]
    n = len(order)
    Z, marg = M.infer(factors, n)
    if Z != forward_Z(factors, n):
        return ('Z', n, Z, forward_Z(factors, n))
    if Z == 0:
        return ('ZP', n, 0, 0)
    for i in range(n):
        for t in (0, 1, 2):
            ze = Z_evidence(factors, n, i, t)
            if ze != marg[i][t]:
                return ('MARG', n, (i, t, ze, marg[i][t]), None)
    return ('OK', n, len(final), len(rounds))


def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    fails = 0
    ok = 0
    zp = 0
    hist = {}
    maxround = 0
    for seed in range(lo, hi):
        r = gen_cyclic(seed)
        if r is None:
            continue
        if r[0] == 'OK':
            ok += 1
            hist[r[1]] = hist.get(r[1], 0) + 1
            maxround = max(maxround, r[3])
        elif r[0] == 'ZP':
            zp += 1
        else:
            print('seed', seed, 'FAIL', str(r)[:400])
            fails += 1
            if fails > 3:
                break
    ks = sorted(hist)
    print('ok', ok, 'fails', fails, 'zero-partition', zp,
          'max rounds', maxround)
    if ks:
        print('core sizes: min', ks[0], 'max', ks[-1], 'total links',
              sum(hist.values()))
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
